using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
public enum Direction { Income, Expense }

public record Transaction(int Id, Direction Dir, decimal Amount, string Category, string Description, DateTime Date);

public record AddResult(bool Ok, string Error);

tests.code:
var ok = new Transaction(1, Direction.Income, 100m, "salary", "pay", new DateTime(2026, 5, 1));
var r = Solution.Validate(ok);
Cj.True(r.Ok, "valid passes");
Cj.Eq(r.Error, null, "no error on success");

var bad = new Transaction(2, Direction.Expense, 0m, "food", "x", new DateTime(2026, 5, 2));
var r1 = Solution.Validate(bad);
Cj.False(r1.Ok, "zero amount");
Cj.Eq(r1.Error, "amount-must-be-positive", "reason pinned");
var r2 = Solution.Validate(bad with { Amount = -5m, Category = " " });
Cj.False(r2.Ok, "blank category");
Cj.Eq(r2.Error, "amount-must-be-positive", "first failure wins");
var r3 = Solution.Validate(bad with { Amount = 5m, Category = "food", Description = new string('d', 60) });
Cj.True(r3.Ok, "60-char description stays valid");
var r4 = Solution.Validate(bad with { Amount = 5m, Description = new string('d', 101) });
Cj.False(r4.Ok, "101-char description rejected");
Cj.Eq(r4.Error, "description-too-long", "length reason pinned");
